// Meta calls GET .../whatsapp/webhook with hub.mode, hub.verify_token,
// hub.challenge query params whenever the webhook subscription is
// (re-)verified from the Meta App dashboard.
//
// WHATSAPP_VERIFY_TOKEN is a plain shared secret with no purpose-built n8n
// credential type -- it's neither an outbound auth header nor HMAC key
// material, just a static string Meta echoes back to prove it was
// configured with the right value. Read via $env as a documented, narrow
// exception -- same posture as SLACK_WEBHOOK_URL in
// docs/security/credential-management.md ("a bearer secret with no
// dedicated n8n credential type, not worth a generic-credential
// workaround for one comparison").
//
// Requirement 6 (never expose the token in logs or response data): this
// node never logs headers/query, and its output carries only a boolean
// plus the (non-secret) challenge string -- never receivedToken or
// expectedToken themselves.
const query = $json.query || {};
const mode = query['hub.mode'];
const receivedToken = query['hub.verify_token'];
const challenge = query['hub.challenge'];

const expectedToken = $env.WHATSAPP_VERIFY_TOKEN || '';
const verified = mode === 'subscribe'
  && typeof receivedToken === 'string'
  && expectedToken.length > 0
  && receivedToken === expectedToken;

return [{
  json: {
    verified,
    challenge: verified ? String(challenge ?? '') : null,
  },
}];

// Meta's WhatsApp Business Account webhook envelope:
// { object: 'whatsapp_business_account', entry: [ { id, changes: [ { value: {
//   metadata: { phone_number_id }, contacts: [...], messages: [...] |
//   statuses: [...] } } ] } ] }
// (https://developers.facebook.com/docs/graph-api/webhooks/getting-started).
// Meta can batch multiple entries/changes/messages in a single call, and
// sends BOTH inbound messages and status callbacks (delivered/read) through
// this same endpoint -- both are handled defensively here rather than
// assuming exactly one text message per call. Only `messages` are surfaced
// downstream; status-only payloads are still a valid, ack'd WhatsApp event
// (handled by "Has Messages?"), just nothing to normalize yet.
let body = $json.body;
if (typeof body === 'string') {
  try {
    body = JSON.parse(body);
  } catch (error) {
    return [{ json: { valid: false, reason: 'Malformed JSON body.', messages: [] } }];
  }
}

if (!body || typeof body !== 'object') {
  return [{ json: { valid: false, reason: 'Empty or non-object body.', messages: [] } }];
}

if (body.object !== 'whatsapp_business_account') {
  return [{ json: { valid: false, reason: `Not a WhatsApp Business Account event (object: ${body.object}).`, messages: [] } }];
}

const messages = [];
for (const entry of (Array.isArray(body.entry) ? body.entry : [])) {
  const whatsappBusinessAccountId = entry.id || null;

  for (const change of (Array.isArray(entry.changes) ? entry.changes : [])) {
    const value = change.value || {};
    const metadata = value.metadata || {};
    const phoneNumberId = metadata.phone_number_id || null;
    const contacts = Array.isArray(value.contacts) ? value.contacts : [];

    for (const message of (Array.isArray(value.messages) ? value.messages : [])) {
      const contact = contacts.find((c) => c.wa_id === message.from) || contacts[0] || {};
      messages.push({
        whatsappBusinessAccountId,
        phoneNumberId,
        customerWhatsappId: message.from || contact.wa_id || null,
        customerDisplayName: (contact.profile && contact.profile.name) || null,
        messageId: message.id || null,
        messageType: message.type || null,
        messageText: message.type === 'text' ? ((message.text && message.text.body) || null) : null,
        timestamp: message.timestamp || null,
        raw: message,
      });
    }
  }
}

return [{ json: { valid: true, reason: null, messages } }];

// Executes AFTER "Respond - Message Received" has already sent the 200 ack
// above (mirrors workflows/crm/01-lead-intake.json's Respond-then-continue
// ordering) so Meta's round-trip isn't held open for this step.
//
// Builds the multi-tenant-ready internal event this gateway exists to
// produce. Tenant RESOLUTION itself -- mapping
// (whatsappBusinessAccountId, phoneNumberId) to an actual EYAN tenant -- is
// explicitly out of scope here; this workflow only guarantees the lookup
// keys are present. A future tenant registry / AI-CRM handoff owns that
// mapping, matching the "Tenant -> WhatsApp Integration -> WABA + Phone
// Number" architecture this gateway is designed not to foreclose.
//
// messageId (Meta's wamid) is the idempotency key a future persistence
// layer should dedupe on -- no dedup store exists yet (out of scope for
// this milestone), so this workflow can re-normalize the same message if
// Meta retries the webhook delivery. That's why the 200 ack above happens
// as early as possible: it's this workflow's main defense against
// unnecessary Meta retries in the meantime.
const parsed = $('Parse WhatsApp Payload').item.json;

return parsed.messages.map((message) => ({
  json: {
    contractVersion: '1',
    workflowExecutionId: $execution.id,
    workflowName: 'whatsapp-gateway-webhook',
    channel: 'whatsapp',
    // Multi-tenant lookup keys -- NOT a resolved tenant.
    whatsappBusinessAccountId: message.whatsappBusinessAccountId,
    phoneNumberId: message.phoneNumberId,
    customerWhatsappId: message.customerWhatsappId,
    customerDisplayName: message.customerDisplayName,
    messageId: message.messageId,
    messageType: message.messageType,
    messageText: message.messageText,
    messageTimestamp: message.timestamp,
    receivedAt: new Date().toISOString(),
    // Original Meta message object, preserved for debugging/auditing.
    rawMessage: message.raw,
  },
}));

// Deliberately gated behind an explicit test keyword (case-insensitive
// EXACT match on the whole inbound message text, checked by "Is Test
// Keyword Message?" upstream) -- this is NOT an auto-reply to every
// inbound message. A human has to type exactly "eyan-test" to trigger it.
//
// No loop risk: Meta status callbacks for OUR own outbound sends (this
// reply included) arrive as `value.statuses`, which "Parse WhatsApp
// Payload"/"Has Messages?" upstream never turn into a normalized message
// in the first place -- they never reach this node or the keyword check
// at all. And even hypothetically, the reply text below is NOT the literal
// string "eyan-test", so it could never re-trigger this same gate.
return [{
  json: {
    to: $json.customerWhatsappId,
    messageType: 'text',
    text: `[EYAN TEST REPLY] Received your test message (id: ${$json.messageId}). This is a controlled reply from the WhatsApp outbound-send capability -- not an automatic response to real customer messages.`,
    contextTag: 'gateway-test-reply',
  },
}];
